const Typesense = require('typesense');
const fs = require('fs');

async function main() {
  const apiKey = fs.readFileSync('/etc/typesense-api-key', 'utf8').trim();
  const client = new Typesense.Client({
    'nodes': [{
      'host': '127.0.0.1',
      'port': '8108',
      'protocol': 'http'
    }],
    'apiKey': apiKey,
    'connectionTimeoutSeconds': 2
  });

  const schema = {
    'name': 'cities',
    'fields': [
      { 'name': 'id', 'type': 'string' },
      { 'name': 'name', 'type': 'string' },
      { 'name': 'country', 'type': 'string' },
      { 'name': 'population', 'type': 'int32' }
    ],
    'default_sorting_field': 'population'
  };

  try {
    console.log('Deleting collection...');
    await client.collections('cities').delete();
  } catch (e) {
    console.log('Collection did not exist or error deleting:', e.message);
  }

  console.log('Creating collection...');
  await client.collections().create(schema);

  console.log('Importing cities...');
  const cities = JSON.parse(fs.readFileSync('/home/user/typeahead/data/cities.json', 'utf8'));
  await client.collections('cities').documents().import(cities, { action: 'upsert' });

  console.log('Searching...');
  const searchResults = await client.collections('cities').documents().search({
    'q': 'San',
    'query_by': 'name',
    'prefix': 'true'
  });

  console.log('Search Results hits:', JSON.stringify(searchResults.hits, null, 2));
}

main().catch(console.error);

