  <title>City Search</title>
  <style>
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background-color: #f7fafc;
      margin: 0;
      padding: 40px 20px;
      display: flex;
      flex-direction: column;
      align-items: center;
    }
    .search-container {
      position: relative;
      width: 100%;
      max-width: 500px;
    }
    #q {
      width: 100%;
      padding: 12px 16px;
      font-size: 16px;
      border: 2px solid #cbd5e0;
      border-radius: 8px;
      outline: none;
      box-sizing: border-box;
      transition: border-color 0.2s;
    }
    #q:focus {
      border-color: #3182ce;
    }
    #suggestions {
      position: absolute;
      top: 100%;
      left: 0;
      right: 0;
      background-color: #ffffff;
      border: 1px solid #e2e8f0;
      border-top: none;
      border-bottom-left-radius: 8px;
      border-bottom-right-radius: 8px;
      box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
      z-index: 10;
      margin-top: 4px;
      overflow: hidden;
    }
    .suggestion {
      padding: 12px 16px;
      cursor: pointer;
      font-size: 15px;
      color: #2d3748;
      transition: background-color 0.1s;
    }
    .suggestion:hover {
      background-color: #f7fafc;
    }
    .suggestion.active {
      background-color: #ebf8ff;
      border-left: 4px solid #3182ce;
      padding-left: 12px;
    }
    mark {
      background-color: #feebc8;
      color: #c05621;
      font-weight: bold;
      padding: 0 2px;
      border-radius: 2px;
    }
  </style>
</head>
<body>
  <div class="search-container">
    <input type="text" id="q" placeholder="Search cities..." autocomplete="off" autofocus>
    <div id="suggestions"></div>
  </div>

  <script>
    const input = document.getElementById('q');
    const suggestionsContainer = document.getElementById('suggestions');

    let suggestionsData = [];
    let activeIndex = -1;

    // Debounce helper
    function debounce(func, wait) {
      let timeout;
      return function(...args) {
        clearTimeout(timeout);
        timeout = setTimeout(() => func.apply(this, args), wait);
      };
    }

    // Clear dropdown and reset state
    function closeDropdown() {
      suggestionsContainer.innerHTML = '';
      suggestionsData = [];
      activeIndex = -1;
    }

    // Update active suggestion class in DOM
    function updateActiveSuggestion() {
      const elements = suggestionsContainer.querySelectorAll('.suggestion');
      elements.forEach((el, index) => {
        if (index === activeIndex) {
          el.classList.add('active');
        } else {
          el.classList.remove('active');
        }
      });
    }

    // Render suggestions in DOM
    function renderSuggestions(data) {
      suggestionsContainer.innerHTML = '';
      suggestionsData = data;
      activeIndex = -1;

      data.forEach((suggestion, index) => {
        const div = document.createElement('div');
        div.className = 'suggestion';
        div.innerHTML = suggestion.name; // suggestion.name contains the <mark> tags

        div.addEventListener('click', () => {
          window.location.href = \`/item/\${suggestion.id}\`;
        });

        suggestionsContainer.appendChild(div);
      });
    }

    // Fetch matching suggestions from API
    const fetchSuggestions = debounce(async (query) => {
      const trimmed = query.trim();
      if (!trimmed) {
        closeDropdown();
        return;
